//! Inline SVG icons (lucide, ISC licence): one element per icon, drawn with `currentColor`, sized by the
//! caller's Tailwind classes (`w-4 h-4`). The geometry lives in `icons_data.rs`, generated by
//! `tools/gen-kima-web-icons.mjs`.

use vertigo::{DomElement, DomNode};

use crate::icons_data::shapes;

/// The icon `name` (lucide's kebab-case name) with `class` on the `<svg>`. An unknown name draws an empty svg.
pub fn icon(name: &'static str, class: &'static str) -> DomNode {
    let svg = DomElement::new("svg")
        .attr_static("xmlns", "http://www.w3.org/2000/svg")
        .attr_static("width", "24")
        .attr_static("height", "24")
        .attr_static("viewBox", "0 0 24 24")
        .attr_static("fill", "none")
        .attr_static("stroke", "currentColor")
        .attr_static("stroke-width", "2")
        .attr_static("stroke-linecap", "round")
        .attr_static("stroke-linejoin", "round")
        .attr_static("aria-hidden", "true")
        .attr("class", class);
    for (tag, attrs) in shapes(name).unwrap_or(&[]) {
        let mut shape = DomElement::new(*tag);
        for (k, v) in *attrs {
            shape = shape.attr_static(k, v);
        }
        svg.add_child(shape);
    }
    svg.into()
}

#[cfg(test)]
mod tests {
    use crate::icons_data::shapes;

    #[test]
    fn known_icons_have_geometry_and_unknown_ones_do_not() {
        assert!(!shapes("play").unwrap().is_empty());
        assert!(shapes("no-such-icon").is_none());
    }
}
